@Tags(['integration'])
@Timeout(Duration(minutes: 15))
/// fa-side omp REG parity leg (issue #810, S7): boots the real fa CLI in a
/// PTY against the SAME scripted mock the omp reference capture used, and
/// structurally diffs the live fa screens against the committed omp
/// reference twins (`test/integration/screenshots/omp_ref/`):
///
/// - boot screens: chrome row count + status-bar segment
///   presence/order/shape (volatile fields scrubbed by the normalizer);
/// - tool-call / code-block turns: chrome inventory (border-heavy card
///   rows, fence rows) + the turn anchor, both sides;
/// - status-bar band: a theme-token pixel comparison of the #121212 band
///   between the two TerminalView renders (same pipeline, so fills must
///   match).
///
/// SKIPS with a named reason when the reference fixtures have not been
/// captured yet — CI only diffs, never captures (issue #810). Manual run:
///   cd flutter_app && flutter test test/cli_visual/fa_omp_reg_visual_test.dart --tags integration
library;

import 'dart:io';

import 'package:fa_llm_mock/fa_llm_mock.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:image/image.dart' as img;

import '../golden/golden_test_helper.dart';
import 'cli_visual_harness.dart';
import 'package:flutter_agent_harness/src/cli/omp_reg_normalizer.dart';
import 'package:flutter_agent_harness/src/cli/omp_reg_scenarios.dart';

void main() {
  // Skip decision is made BEFORE the tests are declared: flutter_test has
  // no runtime skip-from-setUpAll, and the PTY legs must never boot
  // without their fixtures (issue #810).
  final repoRoot0 = findRepoRoot();
  final refDir0 = Directory('$repoRoot0/test/integration/screenshots/omp_ref');
  final fixturesReady =
      refDir0.existsSync() &&
      File('${refDir0.path}/provenance.json').existsSync();
  // flutter_test's skip is bool-only; the reason travels in the test name
  // so CI logs still say WHY (issue #810).
  String nameFor(String whenReady) => fixturesReady
      ? whenReady
      : 'SKIP (no omp_ref fixtures): $whenReady — run '
            'omp_ref_capture_test.dart --tags omp-capture on a PTY-capable '
            'host (issue #810)';

  late String repoRoot;
  late String glyph;
  Directory? tempHome;
  Directory? cwdSandbox;
  Directory? faShots;
  MockLlmServer? server;

  setUpAll(() async {
    // flutter_test runs setUpAll even for skipped tests — bail out before
    // booting anything (issue #810).
    if (!fixturesReady) return;
    await ensureGoldenFonts();
    repoRoot = repoRoot0;
    glyph = kRegSeparatorGlyphs['powerline-thin']!;
    server = await MockLlmServer.start(
      script: MockLlmScript.parse(kRegMockScriptYaml),
    );
    // fa-side renders are runtime outputs — they go to a temp dir, never
    // the shared screenshots dir (only omp reference fixtures live there).
    faShots = Directory.systemTemp.createTempSync('fa_reg_shots_');
    // Same git-clean sandbox convention as the omp capture.
    cwdSandbox = Directory.systemTemp.createTempSync('fa_reg_cwd_');
    File('${cwdSandbox!.path}/note.md').writeAsStringSync(kRegNoteContent);
    tempHome = Directory.systemTemp.createTempSync('fa_reg_home_');
    File('${tempHome!.path}/.fah/config.yaml')
      ..createSync(recursive: true)
      ..writeAsStringSync('''
provider: openai-completions
model: $kRegModelId
baseUrl: ${server!.baseUrl}
mode: code
approvalMode: yolo
allowedTools: []
customProviders:
  - name: reg-provider
    apiType: openai
    baseUrl: ${server!.baseUrl}
    modelId: $kRegModelId
tui:
  statusLine:
    # The omp reference capture pins symbolPreset: nerd; mirror the same
    # E0B1 powerline-thin glyph table on the fa side (issue #918).
    nerdSymbols: true
''');
  });

  tearDownAll(() {
    server?.stop();
    final dirs = [faShots, cwdSandbox, tempHome].whereType<Directory>();
    for (final dir in dirs) {
      if (dir.existsSync()) dir.deleteSync(recursive: true);
    }
  });

  Future<CliVisualHarness> bootFa(WidgetTester tester) async {
    final harness = (await tester.runAsync(
      () => CliVisualHarness.spawn(
        repoRoot: repoRoot,
        // Absolute script path: the sandbox is not the repo root.
        executableArgs: ['$repoRoot/bin/fah.dart'],
        workingDirectory: cwdSandbox!.path,
        extraEnv: {'HOME': tempHome!.path},
      ),
    ))!;
    harness.attach(tester);
    await harness.pumpTerminalView();
    await harness.waitForBoot();
    return harness;
  }

  /// Structural boot-screen diff against the committed omp twin.
  List<String> bootDiff(String name) => structuralDiff(
    File('${faShots!.path}/$name.txt').readAsLinesSync(),
    File(
      '$repoRoot/test/integration/screenshots/omp_ref/$name.txt',
    ).readAsLinesSync(),
    surfaceName: name,
    separatorGlyph: glyph,
  );

  testWidgets(
    nameFor('welcome/idle + status bar: fa screen matches omp reference'),
    (tester) async {
      final harness = await bootFa(tester);
      addTearDown(() => harness.close());
      await harness.screenshot(faShots!.path, '01_welcome_idle');
      await harness.screenshot(faShots!.path, '02_status_bar_default');

      expect(
        bootDiff('01_welcome_idle'),
        isEmpty,
        reason: 'welcome/idle chrome drift vs omp',
      );
      expect(
        bootDiff('02_status_bar_default'),
        isEmpty,
        reason: 'status bar drift vs omp reference',
      );
      _pixelCompareBand(faShots!.path, '02_status_bar_default', repoRoot);
    },
    skip: !fixturesReady,
  );

  testWidgets(
    nameFor('streaming turn with one tool call: chrome matches omp'),
    (tester) async {
      final harness = await bootFa(tester);
      addTearDown(() => harness.close());

      // Mirror the omp capture session exactly (issue #918): the reference
      // twin drives the code-block turn first — omp's first turn of a
      // session dispatches with an empty toolset at the pinned commit, so
      // the text-only turn must go first there — and captures the tool
      // turn with the snippet residue above it. fa replays the same
      // sequence so the whole-screen chrome row inventory compares
      // like-for-like.
      harness.sendText(kRegPrompts['code_block']!);
      harness.sendEnter();
      await harness.liveWaitForScreen(
        "print('hello omp parity')",
        timeout: const Duration(minutes: 3),
      );

      harness.sendText(kRegPrompts['tool_call']!);
      harness.sendEnter();
      await harness.liveWaitForScreen(
        kRegNoteMarker,
        timeout: const Duration(minutes: 3),
      );
      await harness.screenshot(faShots!.path, '03_tool_call');

      _diffTurnChrome('03_tool_call', kRegNoteMarker, repoRoot, faShots!.path);
    },
    skip: !fixturesReady,
  );

  testWidgets(nameFor('fenced code block: chrome matches omp'), (tester) async {
    final harness = await bootFa(tester);
    addTearDown(() => harness.close());

    harness.sendText(kRegPrompts['code_block']!);
    harness.sendEnter();
    await harness.liveWaitForScreen(
      "print('hello omp parity')",
      timeout: const Duration(minutes: 3),
    );
    await harness.screenshot(faShots!.path, '04_code_block');

    _diffTurnChrome(
      '04_code_block',
      "print('hello omp parity')",
      repoRoot,
      faShots!.path,
    );
  }, skip: !fixturesReady);
}

/// Turn-screen diff scoped to the SHARED chrome: both sides must show the
/// turn anchor and render the same number of chrome-heavy rows (tool-card
/// borders ≥3 box glyphs per row; code fences = ``` rows). The tool
/// RESULT body differs by design (each CLI formats read output its own
/// way), so raw row counts are not compared on turn screens.
void _diffTurnChrome(
  String name,
  String anchor,
  String repoRoot,
  String faShotsDir,
) {
  final ompLines = File(
    '$repoRoot/test/integration/screenshots/omp_ref/$name.txt',
  ).readAsLinesSync();
  final faLines = File('$faShotsDir/$name.txt').readAsLinesSync();
  final boxRun = RegExp(r'[══║╔╗╚╝╭╮╯╰┌┐└┘─│]');

  int chromeRows(List<String> lines) => lines
      .where(
        (l) =>
            boxRun.allMatches(l).length >= 3 || RegExp(r'^\s*```').hasMatch(l),
      )
      .length;

  // The turn anchor must be on screen on BOTH sides — a stale or
  // mis-captured twin (turn never rendered) would compare vacuously
  // otherwise (issue #810 review).
  expect(
    ompLines.join('\n'),
    contains(anchor),
    reason:
        '$name: omp reference twin is missing the turn anchor — the '
        'twin was captured before the turn rendered; re-capture',
  );
  expect(
    faLines.join('\n'),
    contains(anchor),
    reason: '$name: fa screen is missing the turn anchor',
  );
  expect(
    chromeRows(faLines),
    chromeRows(ompLines),
    reason: '$name: chrome row inventory differs (tool-card borders / fences)',
  );
}

/// Theme-token pixel comparison of the status-bar band: finds the bar band
/// row in the omp reference PNG (the #121212 flat fill), then requires the
/// fa render's same row to match across the width — both renders go through
/// the identical TerminalView pipeline, so fills must be identical;
/// antialiased glyph edges are the tolerated minority.
void _pixelCompareBand(String faShotsDir, String name, String repoRoot) {
  final ompPng = img.decodePng(
    File(
      '$repoRoot/test/integration/screenshots/omp_ref/$name.png',
    ).readAsBytesSync(),
  )!;
  final faPng = img.decodePng(File('$faShotsDir/$name.png').readAsBytesSync())!;
  expect(faPng.width, ompPng.width, reason: 'render geometry drifted');
  expect(faPng.height, ompPng.height, reason: 'render geometry drifted');

  var bandY = -1;
  for (var y = ompPng.height - 1; y >= 0 && bandY < 0; y--) {
    var fillHits = 0;
    var samples = 0;
    for (var x = 0; x < ompPng.width; x += 4) {
      samples++;
      final p = ompPng.getPixel(x, y);
      if ((p.r - 0x12).abs() <= 2 &&
          (p.g - 0x12).abs() <= 2 &&
          (p.b - 0x12).abs() <= 2) {
        fillHits++;
      }
    }
    if (fillHits >= samples / 2) bandY = y;
  }
  expect(
    bandY,
    greaterThanOrEqualTo(0),
    reason: 'omp band fill (#121212) not found in the reference render',
  );

  var equal = 0;
  var total = 0;
  for (final dy in [-1, 0, 1]) {
    final y = bandY + dy;
    if (y < 0 || y >= ompPng.height) continue;
    for (var x = 0; x < ompPng.width; x += 4) {
      total++;
      final a = ompPng.getPixel(x, y);
      final b = faPng.getPixel(x, y);
      if ((a.r - b.r).abs() <= 3 &&
          (a.g - b.g).abs() <= 3 &&
          (a.b - b.b).abs() <= 3) {
        equal++;
      }
    }
  }
  expect(
    equal / total,
    greaterThanOrEqualTo(0.8),
    reason: 'fa band pixels diverge from the omp reference at y=$bandY',
  );
}

@Tags(['reg-parity'])
/// omp REG parity suite — the merge-blocking structural diff (issue #810,
/// S7). Plain `dart test`: no flutter, no PTY, no network.
///
/// For the committed omp reference twins under
/// `test/integration/screenshots/omp_ref/` the suite renders fa's side of
/// the status-bar surface through the production pure-Dart engine
/// (`renderStatusLine` + the default preset — the exact renderer the TUI
/// band composer paints), scrubs volatile fields (model id, path, time,
/// cost — the normalizer), and compares segment presence, order and shape
/// against the committed omp twin. PNG twins get integrity, geometry and
/// theme-token spot checks (package:image): the omp statusLine band
/// background must appear as an exact flat fill.
///
/// When the reference fixtures have not been captured yet, every test SKIPS
/// with a named reason — CI never captures (issue #810); a PTY-capable host
/// runs flutter_app/test/cli_visual/omp_ref_capture_test.dart
/// (--tags omp-capture). The suite is merge-blocking through the EXISTING
/// legs: ci.yml test-core (`dart test` runs it) and the pre-commit hook's
/// test-core stage — same suite, hook/CI marker parity, no new stage. The
/// flutter-side PTY parity (full screens + band pixels) lives in
/// flutter_app/test/cli_visual/fa_omp_reg_visual_test.dart, run by the
/// pty-visual job.
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter_agent_harness/src/cli/tui_status_line.dart';
import 'package:image/image.dart' as img;
import 'package:test/test.dart';

import 'package:flutter_agent_harness/src/cli/omp_reg_normalizer.dart';
import 'package:flutter_agent_harness/src/cli/omp_reg_scenarios.dart';

void main() {
  final repoRoot = findRepoRoot();
  final refDir = Directory('$repoRoot/test/integration/screenshots/omp_ref');
  final glyph = kRegSeparatorGlyphs['powerline-thin']!;

  final provFile = File('${refDir.path}/provenance.json');
  final fixturesReady = refDir.existsSync() && provFile.existsSync();
  final skipReason = fixturesReady
      ? null
      : 'omp reference fixtures not captured yet '
            '(test/integration/screenshots/omp_ref/) — run the capture on a '
            'PTY-capable host: OMP_CHECKOUT=<oh-my-pi checkout @ '
            '$kRegOmpCommit> flutter test '
            'flutter_app/test/cli_visual/omp_ref_capture_test.dart '
            '--tags omp-capture';

  final provenance = fixturesReady
      ? jsonDecode(provFile.readAsStringSync()) as Map<String, dynamic>
      : null;

  test('provenance pins the captured omp commit and scenario list', () {
    expect(
      provenance!['omp_commit'],
      startsWith(kRegOmpCommit),
      reason: 'fixtures must be regenerated when the omp pin moves',
    );
    expect(
      DateTime.tryParse(provenance['captured_at'] as String),
      isNotNull,
      reason: 'capture date is part of the provenance',
    );
    final scenarios = (provenance['scenarios'] as List).cast<String>();
    expect(scenarios, contains('welcome/idle boot screen'));
    expect(scenarios, contains('status bar (default preset, boot)'));
    expect(
      scenarios,
      contains('streaming turn with one tool call (read note.md)'),
    );
    expect(scenarios, contains('fenced code block'));
  }, skip: skipReason);

  test('every scenario has a png+txt twin pair (no orphans)', () {
    final pngs = <String>{};
    final txts = <String>{};
    for (final f in refDir.listSync().whereType<File>()) {
      if (f.path.endsWith('.png')) pngs.add(_stem(f.path));
      if (f.path.endsWith('.txt')) txts.add(_stem(f.path));
    }
    expect(pngs, isNotEmpty, reason: 'no reference captures committed');
    expect(pngs, equals(txts), reason: 'twins must pair: same stems');
  }, skip: skipReason);

  test('png twins decode at the captured render size, uniformly', () {
    // `columns`/`rows` in provenance are terminal CELLS; PNG size is
    // raster pixels — different units, no fixed multiplier (cell size
    // depends on font metrics). The capture therefore records the actual
    // render size, and this suite asserts every twin decodes to exactly
    // that (issue #810 review).
    final geometry = provenance?['geometry'] as Map<String, dynamic>?;
    final renderWidth = geometry?['render_width'] as int?;
    final renderHeight = geometry?['render_height'] as int?;
    expect(
      renderWidth,
      isNotNull,
      reason:
          'provenance.geometry must record render_width '
          '(the capture writes it from the saved PNG)',
    );
    expect(
      renderHeight,
      isNotNull,
      reason:
          'provenance.geometry must record render_height '
          '(the capture writes it from the saved PNG)',
    );
    for (final png in refDir.listSync().whereType<File>().where(
      (f) => f.path.endsWith('.png'),
    )) {
      final decoded = img.decodePng(png.readAsBytesSync())!;
      expect(
        decoded.width,
        renderWidth,
        reason:
            '${_stem(png.path)}: width differs from the captured '
            'render size — mixed-geometry fixture set',
      );
      expect(
        decoded.height,
        renderHeight,
        reason:
            '${_stem(png.path)}: height differs from the captured '
            'render size — mixed-geometry fixture set',
      );
    }
  }, skip: skipReason);

  test('theme token spot check: statusLine band bg fills the bar row', () {
    // omp statusLine bg token #121212 (dark preset) — the band paints it
    // as an exact flat fill (no antialiasing on fills), so a wide pixel
    // run must match within a 2/255 tolerance per channel. The fa↔omp
    // per-pixel comparison at the same row lives in the flutter parity
    // leg where BOTH renders exist.
    const bg = [0x12, 0x12, 0x12];
    final png = refDir.listSync().whereType<File>().firstWhere(
      (f) => _stem(f.path) == '02_status_bar_default',
    );
    final decoded = img.decodePng(png.readAsBytesSync())!;
    var hits = 0;
    for (final pixel in decoded.data!) {
      if ((pixel.r - bg[0]).abs() <= 2 &&
          (pixel.g - bg[1]).abs() <= 2 &&
          (pixel.b - bg[2]).abs() <= 2) {
        hits++;
        if (hits > 50) break;
      }
    }
    expect(
      hits,
      greaterThan(50),
      reason:
          'the omp statusLine band bg (#121212) is absent from the '
          'status-bar capture — wrong fixture or theme drift',
    );
  }, skip: skipReason);

  test('status bar: fa default preset shape equals the omp reference', () {
    final twin = File('${refDir.path}/02_status_bar_default.txt');
    final ompLines = const LineSplitter().convert(twin.readAsStringSync());
    final ompBar = findStatusBarRow(ompLines, glyph);
    expect(
      ompBar,
      isNotNull,
      reason: 'no status bar found in the omp reference twin',
    );

    final columns =
        (provenance?['geometry'] as Map<String, dynamic>?)?['columns']
            as int? ??
        100;
    final faBar = renderFaDefaultBar(columns: columns);
    final ompSig = barSignature(ompBar!, glyph);
    final faSig = barSignature(faBar, glyph);
    // The first real capture (issue #918) surfaced three port-inherent
    // surface differences that whole-bar shape equality cannot survive —
    // documented, not drift:
    // 1. brand-leading segment: fa paints its text logo ('>_Fa', >=1
    //    word), omp a bare π icon (<word:0>);
    // 2. context gauge architecture: omp embeds the band-gap gauge into
    //    the trailing segment behind the powerline cap, fa paints a
    //    separate trailing <pct> segment (and the engine-level render has
    //    no caps — the composer paints those at band level);
    // 3. path fusion: omp's abbreviated cwd fuses with the gauge into a
    //    single <word:N> token, fa presents a clean <path>.
    // What still MUST agree — the shared structural core: the model
    // segment shape (icon + name = <word:2> on both sides), a path
    // segment on the fa side, a gauge-bearing trailing segment on both
    // sides, and bar presence at all.
    expect(
      faSig,
      contains('<word:2>'),
      reason: 'fa bar lost the model segment (icon + name)',
    );
    expect(
      ompSig,
      contains('<word:2>'),
      reason: 'omp reference bar lost the model segment (icon + name)',
    );
    expect(faSig, contains('<path>'), reason: 'fa bar lost the path segment');
    expect(
      faSig.length,
      greaterThanOrEqualTo(ompSig.length),
      reason:
          'segment presence drifted:\n'
          'fa : $faSig\nomp: $ompSig',
    );
  }, skip: skipReason);

  test('separator glyph inventory matches the preset port', () {
    final twin = File('${refDir.path}/02_status_bar_default.txt');
    final ompBar = findStatusBarRow(
      const LineSplitter().convert(twin.readAsStringSync()),
      glyph,
    );
    expect(ompBar, isNotNull);
    expect(
      ompBar!.contains(glyph),
      isTrue,
      reason: 'omp bar lost the powerline-thin separators',
    );
    final faBar = renderFaDefaultBar(columns: 100);
    expect(faBar.contains(glyph), isTrue);
  }, skip: skipReason);
}

/// Renders fa's default-preset status bar through the production engine
/// with the capture scenario's scripted snapshot: the mock's model name, a
/// git-clean sandbox cwd (both sides hide the git segment), the 200k
/// context window at the boot usage, and NO cost — the mock is a zero-cost
/// flat override in models.yml, omp's cost segment hides at $0.00 for flat
/// overrides (verified against omp status-line sources:
/// formatBillingSummary returns undefined), and fa hides unpriced spend.
/// No approvalMode either: omp's modeSegment returns visible:false unless
/// a special mode (plan/vibe/loop/...) is active, so the omp reference bar
/// carries no mode word for a plain yolo boot (issue #918 first capture).
/// The snapshot mirrors that rendered state. Raw width-exact line — the
/// string the TUI band composer paints.
String renderFaDefaultBar({required int columns}) {
  final snapshot = StatusLineSnapshot(
    cwd: '/reg-sandbox-cwd',
    modelName: 'Test Model',
    contextTokens: 46000,
    contextWindow: 200000,
  );
  // The capture pins omp to `symbolPreset: nerd`; mirror that here so both
  // sides render the same E0B1 powerline-thin glyph table (the default
  // preset alone keeps fa on the font-safe fallbacks).
  final spec = resolveStatusLineSpec(const StatusLineConfig(nerdSymbols: true));
  return renderStatusLine(snapshot, spec, columns).join('\n');
}

String _stem(String path) => path
    .split(Platform.pathSeparator)
    .last
    .replaceAll(RegExp(r'\.(png|txt)$'), '');

