      if (!kStatusLineSegmentIds.contains(id)) {
        warn?.call(
          'config tui.statusLine: unknown segment id "$id" — ignored '
          '(known: ${kStatusLineSegmentIds.join(', ')})',
        );
      }
    }
    return [
      for (final id in ids)
