  }
  if (faBar != null && ompBar == null) {
    return <String>['$surfaceName: omp has no status bar, fa does'];
  }
  if (faBar == null || ompBar == null) return const [];
  return _segmentFindings(faBar, ompBar, surfaceName, separatorGlyph);
}

