    }
  });

  testWidgets(captureName, (tester) async {
    final harness = (await tester.runAsync(
      () => CliVisualHarness.spawn(
        repoRoot: repoRoot,
        executable: bunBin,
        executableArgs: [
          '$ompCheckout/packages/coding-agent/src/cli.ts',
          '--model',
          'mockcap/$kRegModelId',
          '--api-key',
          'dummy-reg-capture',
          '--no-lsp',
          '--no-extensions',
          '--no-session',
        ],
        workingDirectory: cwdSandbox!.path,
        extraEnv: {
