    );
    expect(scenarios, contains('fenced code block'));
  }, skip: skipReason);

  test('every scenario has a png+txt twin pair (no orphans)', () {
    final pngs = <String>{};
    final txts = <String>{};
    for (final f in refDir.listSync().whereType<File>()) {
      if (f.path.endsWith('.png')) pngs.add(_stem(f.path));
