const List<String> kStatusLineSegmentIds = [
  'pi',
  'status',
  'model',
  'mode',
  'path',
  'git',
  'pr',
  'subagents',
  'token_in',
  'token_out',
  'token_total',
  'token_rate',
  'cost',
  'context_pct',
  'context_total',
  'time_spent',
