            '(test/integration/screenshots/omp_ref/) — run the capture on a '
            'PTY-capable host: OMP_CHECKOUT=<oh-my-pi checkout @ '
            '$kRegOmpCommit> flutter test '
            'flutter_app/test/cli_visual/omp_ref_capture_test.dart '
            '--tags omp-capture';

